    /**
     * Tests getting all SensorInstances.
     *
     * @return    Collection
     */
    public List<SensorInstance> testGetAll() throws Throwable {
    LOGGER.info( "SensorInstanceTest:testGetAll() - Retrieving Collection of SensorInstances:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all SensorInstance : " );
    List<SensorInstance> collection  = null;

    try {
        // call the static get method on the SensorInstanceService
        collection = service.getAllSensorInstance();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            SensorInstance currEntity  = null;
            Iterator<SensorInstance> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getSensorInstanceId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

